text:
The green anole’s cold-range overfill
A key question is the extent to which the green anole’s range is overfilled on the cold side, meaning what % of its range experiences a minimum annual temperature below it’s CTmin. The plot below shows the minimum annual temperature across all latitudes encompassing the green anole’s range, along with empirically estimated CTmin values from two studies.


Code
# generate CTmin data from studies
ctmin_data_cs &lt;- tibble(
  lat = c(25.9, 28.8, 30.266, 32.75, 33.47),
  ctmin = c(8.5, 7.1, 6.5, 6.4, 6.1),
  study = "Campbell-Staton et al., 2017"
)
ctmin_data_husak &lt;- tibble(
  lat = c(26.51, 29.9, 32.77, 35.44),
  ctmin = 2^c(2.7, 2.85, 2.56, 2.42),
  study = "Husak et al., 2026"
)
ctmin_data &lt;- rbind(ctmin_data_cs, ctmin_data_husak)

eco_data |&gt;
  filter(present == 1) |&gt;
  group_by(lon, lat) |&gt;
  summarise(
    tmin = min(tmin, na.rm = TRUE),
  ) |&gt;
  group_by(lat) |&gt;
  summarise(
    mean_tmin = mean(tmin, na.rm = TRUE),
    min_tmin = min(tmin, na.rm = TRUE),
    max_tmin = max(tmin, na.rm = TRUE),
    .groups = "drop"
  ) |&gt;
  ggplot(aes(x = lat)) +
  geom_ribbon(
    aes(ymin = min_tmin, ymax = max_tmin),
    fill = "lightblue", alpha = 0.5
  ) +
  geom_line(
    aes(y = mean_tmin),
    color = "darkblue",
    size = 1
  ) +
  geom_point(
    data = ctmin_data,
    aes(x = lat, y = ctmin, color = study),
    size = 3
  ) +
  geom_smooth(
    data = ctmin_data,
    aes(x = lat, y = ctmin, color = study),
    method = "lm",
    se = FALSE,
    fullrange = TRUE,
  ) +
  geom_hline(
    yintercept = 0,
    linetype = "dashed",
    color = "red"
  ) +
  scale_color_manual(
    values = c("darkorange", "purple"),
    name = expression(paste("Empirical CT"[min]," from:"))
  ) +
  scale_x_continuous(
    expand = c(0, 0)
  ) +
  labs(
    x = "Latitude (°N)",
    y = expression(paste("Minimum Annual Temperature (°C)"))
  ) +
  theme_minimal() +
  theme(
    legend.position = c(0.75, 0.9),
    legend.text = element_text(size = 10),
    axis.title = element_text(size = 12),
    axis.text = element_text(size = 10),
    axis.line = element_line(),
    axis.ticks = element_line(),
    panel.grid = element_blank()
  ) +
  coord_cartesian(xlim = c(25, 37.5))









Based on this pattern, we can assess that, even in the most generous scenario, the green anole’s range is overfilelled on the cold side by &gt; 87% of its range based on the lowest empirically estimated CTmin value. Further, &gt; 25% of its range falls below 0°C. The table below summarizes the proportion of the green anole’s range that falls below the lowest, average, and maximum empirically estimated CTmin values.


Code
# table proportions of range falling below lowest, average and maximum CTmin
eco_data |&gt;
  filter(present == 1) |&gt;
  group_by(lon, lat) |&gt;
  summarise(
    tmin = min(tmin, na.rm = TRUE),
  ) |&gt;
  mutate(
    below_lowest_ctmin = tmin &lt; min(ctmin_data$ctmin, na.rm = TRUE),
    below_avg_ctmin = tmin &lt; mean(ctmin_data$ctmin, na.rm = TRUE),
    below_max_ctmin = tmin &lt; max(ctmin_data$ctmin, na.rm = TRUE),
    below_0 = tmin &lt; 0
  ) |&gt;
  ungroup() |&gt;
  summarise(
    prop_below_lowest_ctmin = mean(below_lowest_ctmin, na.rm = TRUE),
    prop_below_avg_ctmin = mean(below_avg_ctmin, na.rm = TRUE),
    prop_below_max_ctmin = mean(below_max_ctmin, na.rm = TRUE),
    prop_below_0 = mean(below_0, na.rm = TRUE),
  ) |&gt;
  pivot_longer(
    cols = everything(),
    names_to = "ctmin_category",
    values_to = "proportion"
  ) |&gt;
  mutate(
    ctmin_value = case_when(
      ctmin_category == "prop_below_lowest_ctmin" ~ round(min(ctmin_data$ctmin, na.rm = TRUE), 2),
      ctmin_category == "prop_below_avg_ctmin" ~ round(mean(ctmin_data$ctmin, na.rm = TRUE), 2),
      ctmin_category == "prop_below_max_ctmin" ~ round(max(ctmin_data$ctmin, na.rm = TRUE), 2),
      ctmin_category == "prop_below_0" ~ 0
    ),
    ctmin_category = case_when(
      ctmin_category == "prop_below_lowest_ctmin" ~ paste("Lowest CTmin - ", ctmin_value, "°C"),
      ctmin_category == "prop_below_avg_ctmin" ~ paste("Average CTmin - ", ctmin_value, "°C"),
      ctmin_category == "prop_below_max_ctmin" ~ paste("Maximum CTmin - ", ctmin_value, "°C"),
      ctmin_category == "prop_below_0" ~ paste("0°C (Freezing Threshold)")
    )
  ) |&gt;
  select(-ctmin_value) |&gt;
  rename(
    "Threshold" = ctmin_category,
    "Proportion of Range Below" = proportion
  ) |&gt;
  kable() |&gt;
  kable_styling(
    full_width = FALSE,
    position = "center"
  )





