ibutton &lt;- readRDS("data/ibutton-data.rds")

# summarise iButton data to get monthly minimum temperatures
ibutton_val &lt;- ibutton |&gt;
  filter(temp &gt; -9) |&gt;
  group_by(location, doy, id, microhabitat) |&gt;
  summarise(
    min_temp = min(temp, na.rm = TRUE),
    .groups = "drop"
  ) |&gt;
  mutate(
    month = doy %/% 30 + 1,
    month = ifelse(month &gt; 12, 12, month)
  ) |&gt;
  group_by(location, month, id, microhabitat) |&gt;
  summarise(
    min_temp = mean(min_temp, na.rm = TRUE),
    .groups = "drop"
  ) |&gt;
  group_by(location, id, microhabitat) |&gt;
  filter(min_temp == min(min_temp, na.rm = TRUE)) |&gt;
  ungroup()

# define locations of interest
locations &lt;- tibble(
  location = c("MIA", "PSL", "ORL", "GNV", "ATL"),
  lon = c(-80.1918, -80.3256, -81.3792, -82.3248, -84.3880),
  lat = c(25.7617, 27.305, 28.5383, 29.6516, 33.7490)
)

# filter microclimate temps to only include locations only
# within 0.1 degrees of the defined locations
microclimate_temps_locations &lt;- microclimate_temps |&gt;
  filter(
    purrr::pmap_lgl(
      list(lon, lat),
      ~ any(abs(.x - locations$lon) &lt; 0.1 & abs(.y - locations$lat) &lt; 0.1)
    )
  )

# add location labels to microclimate temps
microclimate_temps_locations_sum &lt;- microclimate_temps_locations |&gt;
  mutate(
    location = purrr::pmap_chr(
      list(lon, lat),
      ~ locations$location[which.min(abs(.x - locations$lon) + abs(.y - locations$lat))]
    )
  ) |&gt;
  filter(
    as.character(z) %in% c("-0.05", "2.2")
  ) |&gt;
  group_by(location, z) |&gt;
  summarise(
    mean_min_annual_temp = mean(min_annual_temp, na.rm = TRUE),
    min_min_annual_temp = min(min_annual_temp, na.rm = TRUE),
    max_min_annual_temp = max(min_annual_temp, na.rm = TRUE),
    .groups = "drop",
    mean_lat = mean(lat, na.rm = TRUE)
  ) |&gt;
  mutate(
    microhabitat = ifelse(z &lt; 0, "leaflitter", "branch")
  )

# merge iButton data with microclimate temps
validation_data &lt;- ibutton_val |&gt;
  left_join(
    microclimate_temps_locations_sum,
    by = c("location", "microhabitat")
  ) |&gt;
  mutate(
    microhabitat = factor(microhabitat, levels = c("leaflitter", "branch")),
    location = factor(location, levels = microclimate_temps_locations_sum |&gt; distinct(location, mean_lat) |&gt; arrange(mean_lat) |&gt; pull(location))
  )

validation_data |&gt;
  ggplot(aes(x = mean_min_annual_temp, y = min_temp + 2, color = microhabitat)) +
  geom_smooth(aes(fill = microhabitat), method = "lm", linewidth = 1, alpha = 0.1) +
  geom_point(aes(shape = location), size = 3) +
  geom_abline(slope = 1, intercept = 0, linetype = "dashed", color = "black") +
  theme_minimal() +
  scale_color_manual(
    values = c("leaflitter" = "darkorange", "branch" = "forestgreen"),
    name = "Microhabitat",
    labels = c("Leaf Litter", "Canopy")
  ) +
  scale_fill_manual(
    values = c("leaflitter" = "darkorange", "branch" = "forestgreen"),
    name = "Microhabitat",
    labels = c("Leaf Litter", "Canopy")
  ) +
  scale_shape_manual(
    name = "Location",
    values = c(15, 16, 17, 18, 19),
    labels = c("MIA", "PSL", "ORL", "GNV", "ATL")
  ) +
  theme(
    legend.position = "right",
    legend.title = element_text(size = 12),
    legend.text = element_text(size = 10),
    axis.title = element_text(size = 12),
    axis.text = element_text(size = 10),
    panel.grid = element_blank(),
    axis.line = element_line(color = "black", linewidth = 0.5),
    axis.ticks = element_line(color = "black", linewidth = 0.5)
  ) +
  labs(
    x = "Predicted minimum operative temperature (°C)",
    y = "Observed operative temperature (°C)"
  ) 


